import { applyProposal, proposeAdjustment } from "./adjust";
import { addDays, fromISODate, type ISODate, startOfWeek, todayISO } from "./dates";
import { getExercise } from "./exercises";
import { plannedSessionFor } from "./plan";
import type { AppData, Difficulty } from "./schema";
import { completeSet, finishSession, startSession, updateSetValues } from "./session";
import { addMemory, completeOnboarding, createEmptyData } from "./state";

/**
 * Sample data for "Explore the demo". It lives under a separate storage key
 * and is generated by running the real domain logic, so it behaves exactly
 * like real data — but it is never mixed into a real user's history.
 */

function at(date: ISODate, hour: number) {
  const d = fromISODate(date);
  d.setHours(hour, 0, 0, 0);
  return d.getTime();
}

function train(data: AppData, date: ISODate, sets: number | "all", difficulty: Difficulty, loadBump = 0): AppData {
  const planned = plannedSessionFor(data, date);
  if (!planned) return data;
  let t = at(date, 18);
  let s = startSession(data, planned, t);
  const total = s.exercises.reduce((n, e) => n + e.sets.length, 0);
  const target = sets === "all" ? total : sets;
  let done = 0;
  s.exercises.forEach((ex, i) => {
    ex.sets.forEach((_, j) => {
      if (done >= target) return;
      t += 90_000;
      // Only exercises that use external load get a weight recorded.
      if (getExercise(ex.exerciseId)?.loaded) {
        s = updateSetValues(s, i, j, { loadKg: (s.exercises[i].sets[j].loadKg ?? 8) + loadBump });
      }
      s = completeSet(s, i, j, t);
      done++;
    });
  });
  return finishSession({ ...data, activeSession: s }, { difficulty, energy: "okay" }, t + 60_000).data;
}

export function createDemoData(now: number): AppData {
  const today = todayISO(new Date(now));
  const start = addDays(startOfWeek(today), -14);
  let d = completeOnboarding(
    createEmptyData("demo"),
    {
      name: "Jordan",
      experience: "new",
      goal: "strength",
      location: "both",
      daysPerWeek: 3,
      sessionMinutes: 30,
      limitations: [],
      limitationsStatus: "answered",
      twinColor: "coral",
      twinNickname: "Pip",
    },
    at(start, 8),
  );
  d = { ...d, onboarding: { ...d.onboarding, completed: true } };

  // Week 1: all three sessions.
  d = train(d, start, "all", "about-right");
  d = train(d, addDays(start, 2), "all", "about-right");
  d = train(d, addDays(start, 4), "all", "too-easy");
  // Week 2: one shortened session, one partial.
  const w2 = addDays(start, 7);
  const r = proposeAdjustment({ data: d, date: w2 }, { reason: "less-time", minutes: 15 });
  if (r.ok) d = applyProposal(d, r.proposal, "today", at(w2, 7));
  d = train(d, w2, "all", "about-right", 2);
  d = train(d, addDays(w2, 2), 4, "about-right", 2);
  // This week: train on Monday if it has already passed.
  const w3 = startOfWeek(today);
  if (w3 < today) d = train(d, w3, "all", "about-right", 2);

  d = addMemory(d, { text: "Prefers training in the evening", category: "schedule", source: "you-told-coach" }, now);
  return {
    ...d,
    mode: "demo",
    twin: { ...d.twin, mode: "competitive", equipped: ["sunglasses"] },
    meals: {
      prefs: {
        currency: "GBP",
        weeklyBudget: 45,
        people: 1,
        diet: "none",
        allergies: [],
        cookingTime: "medium",
        pantry: ["rice", "olive oil"],
        updatedAt: now,
      },
      saved: ["chickpea-curry", "egg-fried-rice"],
    },
    explore: { saved: ["sample-run-club"] },
  };
}
